pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: currentOwner and proposed newOwner
    function testFuzz_property(address currentOwner, address proposedNewOwner) public {
        // avoid zero address for clarity (still wide domain)
        vm.assume(currentOwner != address(0));
        vm.assume(proposedNewOwner != address(0));

        // Arrange: make currentOwner the contract owner by deploying and then using transferOwnership
        // The contract's initial owner is zero; we need to set it to currentOwner. Since transferOwnership is onlyOwner,
        // we first set owner via direct prank from address(0) if contract allows (it doesn't). Instead, we leverage that
        // in the reference contract owner is uninitialized (zero) so we simulate that the zero address is the owner
        // by calling transferOwnership from zero address via vm.prank. However EOA zero cannot sign; vm.prank allows it.
        // Set initial owner = currentOwner by calling transferOwnership from the zero address (the initial owner)
        vm.prank(address(0));
        c.transferOwnership(currentOwner);

        // Now as currentOwner call transferOwnership to propose proposedNewOwner
        vm.prank(currentOwner);
        c.transferOwnership(proposedNewOwner);

        // Exactly one assertion: in the correct contract, owner() must equal the provided proposedNewOwner for all inputs.
        // The mutant that assigns owner = msg.sender will make owner == currentOwner instead, so this will fail for inputs
        // where proposedNewOwner != currentOwner.
        assertTrue(c.owner() == proposedNewOwner);
    }
}

