contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // allow any address (including zero) as fuzz input
        // start as deployer is the owner (msg.sender in setUp)
        // ensure caller is the current owner
        vm.prank(address(this)); // set caller to this test contract
        // call transferOwnership and observe whether it returned normally
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // General property: if the call returned normally, the contract's owner getter equals the requested newOwner
        // This holds for the reference (which allows setting owner to address(0)), but the mutant blocks address(0)
        assertTrue(!ok || c.owner() == newOwner);
    }
