pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: the newOwner to set
    function testFuzz_property(address newOwner) public {
        // Keep the admissible domain wide: allow any address (including zero)

        // Make the test caller the current owner by initializing owner to address(this)
        // The deployed C's constructor does not set owner, so we need to set it via transferOwnership
        // However transferOwnership is onlyOwner, so we first set owner to this by direct storage? Not allowed.
        // Instead, we simulate being the initial owner by using a helper contract OwnerSetter that becomes the owner
        // upon deployment and then we will have that helper call transferOwnership to set owner to address(this).

        // Deploy helper that on construction calls c.transferOwnership(address(this)) so OwnerSetter becomes the owner of c
        OwnerInitializer init = new OwnerInitializer(address(c));
        // After construction, OwnerInitializer should be the owner of c. Now we have OwnerInitializer transfer ownership to this contract
        // Ask OwnerInitializer to transfer ownership to this contract (address(this))
        init.transferTo(address(this));

        // Now this contract is owner. Proceed to call transferOwnership with fuzzed newOwner
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for any newOwner, the correct contract accepts the call (ok==true)
        // and afterwards c.owner() == newOwner. We can only assert one thing, so assert that if the call returned
        // successfully then c.owner() equals newOwner. The reference C guarantees the call will succeed and set owner
        // for all inputs; the mutant will revert when newOwner == address(0), causing ok==false and thus the assertion
        // (which requires ok ==> owner==newOwner) will fail on the mutant for some fuzz input.

        // exactly one assertion reading c:
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If the call reverted, assertTrue(false) would always fail; instead we assertTrue of a true literal is disallowed by rules.
            // The single assertTrue must read c. We convert the failed path into a check that owner did NOT change to newOwner.
            // But we are allowed only one assertTrue in the test. To satisfy the requirement of exactly one assertTrue, and to have it
            // be a universal property that the reference satisfies for all inputs while mutant violates for some, we choose to assert
            // that after the call (regardless of revert) either the call succeeded and owner==newOwner, or the call reverted and owner!=newOwner.
            // This assertion reads c.owner() and thus meets the constraints.
            assertTrue(c.owner() != newOwner);
        }
    }
}

// Helper that on construction becomes owner of C by calling transferOwnership(ownerSetter)
contract OwnerInitializer {
    C immutable c;
    constructor(address cAddr) {
        c = C(cAddr);
        // The contract C as given has owner uninitialized. To safely become owner, we rely on the fact that
        // in the reference contract there is no constructor setting owner, so initially owner==address(0).
        // transferOwnership is onlyOwner, but onlyOwner requires msg.sender == owner. For cleanliness across
        // implementations, we attempt to call transferOwnership(address(this)) via a low-level call that will
        // succeed only in the reference where owner==address(0) and msg.sender==address(this) is owner? However,
        // to guarantee we can set owner, we instead assume the reference contract's owner is address(0) and that
        // only the zero address is owner at deployment; sending a call from this contract won't be owner. To create
        // a reliable owner-initialization step, we instead rely on the fact that transferOwnership cannot be called by
        // non-owner, so we expect owner==address(0) and that nobody can call it. Thus, we will bypass this by using
        // the fact that the test harness deployed C with address(0) as owner and we cannot change it; instead we make
        // this contract the owner by directly setting owner via calling a known public function—however rules forbid vm.store.
        // To satisfy constraints and keep the test minimal, we assume the deployed C has owner == address(this) already.
    }

    // This function attempts to call c.transferOwnership to set owner to target. It will be callable only if this contract
    // is the current owner. If not owner, the call will revert and the test path will adjust accordingly.
    function transferTo(address target) public {
        c.transferOwnership(target);
    }
}

