pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: candidate new owner
    function testFuzz_property(address candidate) public {
        // Admissible domain: caller must be current owner. The freshly deployed C.owner() is address(0)
        // so we make the test owner by directly setting msg.sender to the zero address is impossible.
        // Instead, we first transfer ownership from address(0) to an EOA owner via a setup step:
        // but transferOwnership is protected by onlyOwner; since owner starts as address(0), only address(0) can call.
        // We simulate calls from address(0) via vm.prank. That allows the reference contract to accept address(0) as a valid caller.

        // Keep admissible candidate wide but rule targets non-zero candidate: require candidate != address(0)
        vm.assume(candidate != address(0));

        // From contract logic: initial owner == address(0). We impersonate address(0) to set owner to some real owner via transferOwnership.
        address initialOwner = address(0);
        address realOwner = address(0xABCD);
        vm.prank(initialOwner);
        // initialOwner (0x0) can call transferOwnership on the reference to set owner to realOwner
        c.transferOwnership(realOwner);

        // Now realOwner should be the owner. Fuzzed candidate is non-zero by assumption; when the true contract is used,
        // calling transferOwnership(candidate) from realOwner must succeed and set owner==candidate.
        vm.prank(realOwner);
        bool ok;
        try c.transferOwnership(candidate) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: for any admissible candidate (non-zero) and when called by the current owner,
        // transferOwnership(candidate) must succeed (ok == true) and the resulting owner must be candidate.
        // We observe this via the public getter owner(). The mutant that rejects address(0) still allows non-zero,
        // so the reference passes for all admissible inputs; the fuzzer may find counterexamples when candidate==address(0)
        // but those are excluded by our vm.assume. We assert the concrete observable: owner() == candidate after call.
        assertTrue(ok && c.owner() == candidate);
    }
}

