pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the actor who will be set as owner initially and then call owned()
    function testFuzz_property(address actor) public {
        // avoid the zero address to keep domain wide but meaningful
        vm.assume(actor != address(0));

        // Make actor the owner by calling transferOwnership from the deployer (setUp deployer is address(this))
        // First, ensure the deployer is the initial owner: the reference contract's owner is default zero until transfer;
        // but transferOwnership is onlyOwner, so we need to set owner to deployer first. Many contracts set owner in constructor,
        // but given we don't know, attempt to set owner by calling transferOwnership must be done by current owner.
        // To be robust across both possible reference and mutant, we will directly set owner by calling c.transferOwnership from address(this)
        // Only works if address(this) is owner. If it's not, we cannot change owner; instead, we check current owner and proceed accordingly.

        address initialOwner = c.owner();

        // If current owner is not this test contract, we attempt to make actor the owner only if current owner equals this test contract.
        // To keep the test universal and simple, we will proceed only when this contract is the owner or when actor already equals current owner.
        // Ensure we have a scenario where actor is the owner before calling owned(): either make actor the owner if possible, or skip otherwise.

        if (initialOwner == address(this)) {
            // set actor as owner
            c.transferOwnership(actor);
            // confirm
            assert(c.owner() == actor);
        } else {
            // If this contract is not owner, try to set owner to actor only if actor equals initialOwner
            // Otherwise we cannot make actor the owner without more privileges; in that case we narrow to inputs where actor is current owner
            vm.assume(actor == initialOwner);
        }

        // At this point, actor is the owner
        assert(c.owner() == actor);

        // Have actor call owned()
        vm.prank(actor);
        bool ok;
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL ASSERTION: calling owned() while msg.sender == owner MUST NOT change owner.
        // Read the owner getter and assert it remains equal to actor.
        // This is the single assertTrue required.
        assertTrue(c.owner() == actor);
    }
}

