pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed param: an address that will be used as the caller for owned()
    function testFuzz_property(address caller) public {
        // restrict to a non-zero address to avoid zero-address edge cases
        vm.assume(caller != address(0));

        // Set contract owner initially to some address (use this test contract)
        // We need to set owner on C. transferOwnership is onlyOwner, and owner is default 0.
        // To make this test meaningful, we first set owner to address(this) by low-level init:
        // deploy a fresh C where owner is zero then directly set owner via calling transferOwnership
        // But transferOwnership is onlyOwner; owner is zero so we cannot call it. Instead, treat zero-owner as allowed
        // The intended contract C has owner uninitialized (zero). To create an owner for the test, we will
        // impersonate the zero address is impossible. Instead, we will not change initial owner and assert relation
        // relative to current owner value. Read the current owner, then call owned() as that owner and check it doesn't change.

        address initialOwner = c.owner();

        // If initialOwner is zero, we cannot call owned() as owner because onlyOwner requires msg.sender==owner.
        // The intended universal rule: for any caller, calling owned() should not change owner. To exercise the case
        // where caller is owner, we need to ensure the call is made by the current owner; otherwise the call will revert.
        // We only keep cases where caller equals the current owner OR not; both are admissible. We will perform the call
        // using vm.prank(caller). If the call reverts for non-owner callers, that's acceptable; the reference behavior
        // is that the call reverts for non-owner callers and does not change owner for owner callers. The mutant may
        // not revert and may change owner when caller==owner.

        // Prepare to call owned() as caller
        bool ok;
        vm.prank(caller);
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if the call succeeded (ok == true), then owner must remain equal to initialOwner.
        // This expresses the general rule: any successful call to owned() does not change owner.
        // The reference C satisfies this for all callers; the mutant that assigns owner = msg.sender inside owned()
        // will cause this assertion to fail when the caller is equal to initialOwner (call succeeds) and owner changes.
        if (ok) {
            assertTrue(c.owner() == initialOwner);
        } else {
            // If the call reverted, we still assert that owner equals initialOwner (no change happened on revert).
            // This keeps the property universal: after any attempted call, owner remains equal to initialOwner.
            assertTrue(c.owner() == initialOwner);
        }
    }
}

